select p.brand, case when p.category in ('Sports', 'Home') then 'priority' else 'other' end as category_group, count(distinct i.quantity) as unique_stores from inventory i right outer join products p on i.product_id = p.id full outer join stores s on s.id = i.store_id group by p.brand, case when p.category in ('Sports', 'Home') then 'priority' else 'other' end having count(distinct i.quantity) > 4 order by unique_stores desc;
